// SF-063: only server-committed events reach alliance and personal news.
let allianceEventPollBusy=false,allianceTaxBusy=false,allianceTaxPending=null;
function allianceEventContext(){return {snapshot:state,player:state.centralPlayerId,generation:state.centralResetGeneration||0,name:state.alliance?.name,id:state.alliance?.registryId||null};}
function sameAllianceEventContext(before){const now=allianceEventContext();return before.snapshot===now.snapshot&&before.player===now.player&&before.generation===now.generation&&before.name===now.name&&(!before.id||!now.id||before.id===now.id);}
function renderAllianceEventNews(){const root=document.getElementById('allianceContent');if(!root||!state.centralPlayerId||!state.alliance?.name||state.alliance.name==='Unaffiliated')return;let panel=root.querySelector('#allianceEventNews');if(!panel){panel=document.createElement('section');panel.id='allianceEventNews';panel.className='panel';panel.style.marginTop='14px';root.append(panel);}const feed=state.sharedAllianceEvents,events=feed&&feed.generation===(state.centralResetGeneration||0)&&feed.alliance===state.alliance.name?feed.events:[];panel.innerHTML='<div class="ph"><div class="pt">ALLIANCE NEWS</div><span class="meta">CENTRAL EVENT ARCHIVE · MEMBER MAIL DELIVERY</span></div><div class="summary-list">'+(events.length?events.map(event=>'<div class="summary-line"><span>'+esc(event.text)+'</span><small>T'+esc(event.tick)+' · '+esc(event.actor||'Alliance command')+'</small></div>').join(''):'<div class="empty">No central alliance events recorded in this round.</div>')+'</div>';}
async function pollAllianceEvents(){if(allianceEventPollBusy||document.hidden||window.isStaffWorkspace||!state.centralPlayerId||!state.alliance?.name||state.alliance.name==='Unaffiliated')return;const context=allianceEventContext();allianceEventPollBusy=true;try{const data=await centralDirectoryRequest('/api/alliance-events');if(!sameAllianceEventContext(context)||data.generation!==context.generation||data.alliance!==context.name||(context.id&&data.allianceId!==context.id))return;state.sharedAllianceEvents=data;state.allianceEventIds=state.allianceEventIds||[];let changed=false;for(const event of [...data.events].reverse()){if(state.allianceEventIds.includes(event.id))continue;state.allianceEventIds.push(event.id);if(!(state.news||[]).some(entry=>entry.allianceEventId===event.id)){addNews(event.text,'info');Object.assign(state.news[0],{category:'ALLIANCE',allianceEventId:event.id,tick:event.tick,at:event.at});changed=true;}}state.allianceEventIds=state.allianceEventIds.slice(-2000);if(changed){save();if(typeof renderNews==='function')renderNews();}renderAllianceEventNews();}catch(error){const panel=document.getElementById('allianceEventNews');if(sameAllianceEventContext(context)&&panel){let status=panel.querySelector('[data-alliance-event-error]');if(!status){status=document.createElement('p');status.dataset.allianceEventError='';status.setAttribute('role','status');panel.append(status);}status.textContent='Alliance news could not refresh: '+error.message;}}finally{allianceEventPollBusy=false;}}
async function saveCentralAllianceTax(){if(allianceTaxBusy)return;const tax=Number(document.getElementById('allianceTax')?.value);if(!Number.isFinite(tax)||tax<0||tax>5)return notify('Choose an alliance tax from 0 to 5%.',true);const context=allianceEventContext();if(!allianceTaxPending||!sameAllianceEventContext(allianceTaxPending.context)||allianceTaxPending.payload.tax!==tax)allianceTaxPending={context,payload:{action:'tax',tax,generation:context.generation,revision:planetDirectoryRevision,operationId:crypto.randomUUID()}};allianceTaxBusy=true;try{const result=await centralDirectoryRequest('/api/alliance-policy',allianceTaxPending.payload);allianceTaxPending=null;if(!sameAllianceEventContext(context))return;state.alliance.tax=result.tax;planetDirectoryRevision=result.revision;if(typeof refreshAfterCentralWrite==='function')await refreshAfterCentralWrite();await pollAllianceEvents();notify(result.unchanged?'Alliance tax is already set to '+result.tax+'%.':'Alliance tax saved. Alliance news and member mail delivered.');}catch(error){if([400,403,409].includes(error.status))allianceTaxPending=null;notify(error.message,true);}finally{allianceTaxBusy=false;}}
setInterval(()=>pollAllianceEvents(),60000);setTimeout(()=>pollAllianceEvents(),3500);
document.addEventListener('click',event=>{if(event.target.closest('[data-page="alliance"]'))void pollAllianceEvents();});
